ALTER TABLE provider_remunerations ADD COLUMN budget_expense_id BIGINT UNSIGNED NULL AFTER currency,ADD UNIQUE KEY uk_provider_rem_budget_expense(budget_expense_id),ADD CONSTRAINT fk_provider_rem_budget_expense FOREIGN KEY(budget_expense_id) REFERENCES budget_expenses(id) ON DELETE RESTRICT;
CREATE TABLE provider_payment_instruments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,provider_profile_id BIGINT UNSIGNED NOT NULL,instrument_type ENUM('BANK_TRANSFER','MOBILE_MONEY','CHEQUE','CASH') NOT NULL,label VARCHAR(150) NOT NULL,encrypted_payload TEXT NULL,payload_iv VARCHAR(64) NULL,payload_tag VARCHAR(64) NULL,key_version VARCHAR(40) NULL,masked_reference VARCHAR(80) NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by BIGINT UNSIGNED NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_provider_payment_instrument(provider_profile_id,is_active),CONSTRAINT chk_provider_payment_sensitive CHECK((instrument_type IN('BANK_TRANSFER','MOBILE_MONEY') AND encrypted_payload IS NOT NULL AND payload_iv IS NOT NULL AND payload_tag IS NOT NULL AND key_version IS NOT NULL)OR(instrument_type IN('CHEQUE','CASH') AND encrypted_payload IS NULL AND payload_iv IS NULL AND payload_tag IS NULL AND key_version IS NULL)),CONSTRAINT fk_provider_payment_profile FOREIGN KEY(provider_profile_id) REFERENCES provider_profiles(id) ON DELETE RESTRICT,CONSTRAINT fk_provider_payment_creator FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_provider_payment_updater FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE RESTRICT)ENGINE=InnoDB;
CREATE TABLE provider_remuneration_payment_snapshots(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,provider_remuneration_id BIGINT UNSIGNED NOT NULL,budget_expense_disbursement_id BIGINT UNSIGNED NOT NULL,provider_payment_instrument_id BIGINT UNSIGNED NOT NULL,instrument_type VARCHAR(30) NOT NULL,label_snapshot VARCHAR(150) NOT NULL,masked_reference_snapshot VARCHAR(80) NULL,encrypted_payload_snapshot TEXT NULL,payload_iv_snapshot VARCHAR(64) NULL,payload_tag_snapshot VARCHAR(64) NULL,key_version_snapshot VARCHAR(40) NULL,payment_reference VARCHAR(150) NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_provider_rem_disbursement(budget_expense_disbursement_id),CONSTRAINT fk_provider_payment_snapshot_rem FOREIGN KEY(provider_remuneration_id) REFERENCES provider_remunerations(id) ON DELETE RESTRICT,CONSTRAINT fk_provider_payment_snapshot_disbursement FOREIGN KEY(budget_expense_disbursement_id) REFERENCES budget_expense_disbursements(id) ON DELETE RESTRICT,CONSTRAINT fk_provider_payment_snapshot_instrument FOREIGN KEY(provider_payment_instrument_id) REFERENCES provider_payment_instruments(id) ON DELETE RESTRICT,CONSTRAINT fk_provider_payment_snapshot_creator FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT)ENGINE=InnoDB;
CREATE TABLE provider_document_exceptions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,provider_remuneration_id BIGINT UNSIGNED NOT NULL,document_type_id BIGINT UNSIGNED NOT NULL,reason VARCHAR(1000) NOT NULL,status ENUM('REQUESTED','APPROVED','REJECTED') NOT NULL DEFAULT 'REQUESTED',requested_by BIGINT UNSIGNED NOT NULL,requested_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,decided_by BIGINT UNSIGNED NULL,decided_at DATETIME NULL,UNIQUE KEY uk_provider_document_exception(provider_remuneration_id,document_type_id),CONSTRAINT fk_provider_doc_exception_rem FOREIGN KEY(provider_remuneration_id) REFERENCES provider_remunerations(id) ON DELETE RESTRICT,CONSTRAINT fk_provider_doc_exception_type FOREIGN KEY(document_type_id) REFERENCES document_types(id) ON DELETE RESTRICT,CONSTRAINT fk_provider_doc_exception_requester FOREIGN KEY(requested_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_provider_doc_exception_decider FOREIGN KEY(decided_by) REFERENCES users(id) ON DELETE RESTRICT)ENGINE=InnoDB;
INSERT INTO permissions(module,action,code,name,label,group_name,description,is_active)VALUES('hr','manage','hr.provider.payment_method.manage','Gérer les moyens de règlement prestataires','Gérer les moyens de règlement prestataires','RH & Administration','Gestion chiffrée des coordonnées prestataires',TRUE),('hr','view','hr.provider.payment_method.sensitive.view','Consulter les coordonnées sensibles','Consulter les coordonnées sensibles','RH & Administration','Lecture déchiffrée explicitement autorisée',TRUE),('hr','create','hr.provider.remuneration.finance.request','Demander le traitement financier prestataire','Demander le traitement financier prestataire','RH & Administration','Créer une dépense centrale depuis une constatation validée',TRUE),('hr','create','hr.provider.remuneration.disburse','Décaisser une rémunération prestataire','Décaisser une rémunération prestataire','RH & Administration','Décaissement central après contrôles',TRUE),('hr','approve','hr.provider.document_exception.approve','Approuver une exception documentaire','Approuver une exception documentaire','RH & Administration','Décision indépendante et auditée',TRUE)ON DUPLICATE KEY UPDATE name=VALUES(name),label=VALUES(label),group_name=VALUES(group_name),description=VALUES(description),is_active=VALUES(is_active);
INSERT INTO role_permissions(role_id,permission_id,scope)SELECT r.id,p.id,'GLOBAL' FROM roles r CROSS JOIN permissions p WHERE r.code='SUPER_ADMIN' AND r.is_system=TRUE AND r.is_active=TRUE AND(p.code LIKE 'hr.provider.payment_method.%' OR p.code LIKE 'hr.provider.remuneration.finance.%' OR p.code='hr.provider.remuneration.disburse' OR p.code='hr.provider.document_exception.approve')ON DUPLICATE KEY UPDATE scope=VALUES(scope);
